# `meta_V(v)` with `method = :REML` (alone, and beside an ordinary `(1 | g)`), pinned to drmTMB 0.8.1
# `REML = TRUE` (fixtures/meta_v_reml/, regenerated by make_reference.R). Fixed bounds: |logLik diff| <= 1e-4,
# fixed effects within 1e-3 R SE, log SDs within 5e-3, SEs within 1e-3 relative.
# REML criterion (drmTMB puts beta_mu in the random block with a flat prior; Laplace is exact):
#   -logLik_REML = 0.5 [ logdet(Omega) + r' Omega^-1 r + n log 2pi ] + 0.5 logdet(X' Omega^-1 X) - 0.5 p log 2pi,
#   Omega = diag(v_i + sigma^2) + s_g^2 Z Z', r = y - X beta.
using DRModels, Test, DelimitedFiles, LinearAlgebra
using StatsModels: @formula

const _MVR_DIR = joinpath(@__DIR__, "fixtures", "meta_v_reml")
const _MVR_D = let (m, h) = readdlm(joinpath(_MVR_DIR, "data_meta_reml.csv"), ',', Any; header = true)
    h = String.(vec(h)); col(n) = m[:, findfirst(==(n), h)]
    (; g = String.(col("g")), x1 = Float64.(col("x1")), vi = Float64.(col("vi")), yi = Float64.(col("yi")))
end
const _MVR_REF = let (m, h) = readdlm(joinpath(_MVR_DIR, "ref_meta_reml.csv"), ',', Any; header = true)
    Dict((String(m[i, 1]), String(m[i, 2])) => (est = Float64(m[i, 3]), se = m[i, 4] isa Number ? Float64(m[i, 4]) : NaN)
         for i in 1:size(m, 1))
end

function _mvr_check(fit, cell, withre)
    R(k) = _MVR_REF[(cell, k)]
    @test fit.estim_method === :REML
    @test fit.converged
    @test abs(fit.loglik - R("logLik").est) <= 1e-4
    se = sqrt.(diag(fit.vcov))
    for (j, k) in enumerate(["mu:(Intercept)", "mu:x1", "sigma:(Intercept)"])
        @test abs(fit.theta[j] - R(k).est) <= (j <= 2 ? 1e-3 * R(k).se : 5e-3)
        @test abs(se[j] - R(k).se) <= 1e-3 * R(k).se
    end
    withre && @test abs(fit.theta[4] - log(R("sd_g").est)) <= 5e-3
end

@testset "meta_V + REML agrees with R drmTMB 0.8.1" begin
    d = _MVR_D
    @testset "meta_V alone" begin
        fit = drm(bf(@formula(yi ~ x1 + meta_V(vi)), @formula(sigma ~ 1)), Gaussian(); data = d, method = :REML)
        _mvr_check(fit, "meta_reml", false)
        ml = drm(bf(@formula(yi ~ x1 + meta_V(vi)), @formula(sigma ~ 1)), Gaussian(); data = d)
        @test ml.loglik != fit.loglik
        @test reml_loglik(fit) == fit.loglik
        @test ml_loglik(fit) <= ml.loglik + 1e-8     # ML logLik at the REML estimate cannot beat the ML optimum
    end
    @testset "meta_V + (1 | g)" begin
        fit = drm(bf(@formula(yi ~ x1 + meta_V(vi) + (1 | g)), @formula(sigma ~ 1)), Gaussian(); data = d, method = :REML)
        _mvr_check(fit, "meta_re_reml", true)
        # independent oracle: the REML criterion above evaluated densely at the fitted parameters
        n = length(d.yi); X = [ones(n) d.x1]; lv = unique(d.g)
        Z = [d.g[i] == l ? 1.0 : 0.0 for i in 1:n, l in lv]
        Ω = Diagonal(d.vi .+ exp(2fit.theta[3])) + exp(2fit.theta[4]) * Z * Z'
        r = d.yi - X * fit.theta[1:2]
        ll = -0.5 * (logdet(Ω) + dot(r, Ω \ r) + n * log(2π)) - 0.5 * logdet(Symmetric(X' * (Ω \ X))) + 0.5 * 2 * log(2π)
        @test abs(ll - fit.loglik) <= 1e-8
    end
    @testset "unsupported neighbours stay refused" begin
        msg(f; kw...) = try
            drm(f, Gaussian(); data = d, method = :REML, kw...); ""
        catch e
            sprint(showerror, e)
        end
        @test occursin("not implemented", msg(bf(@formula(yi ~ x1 + meta_V(vi)), @formula(sigma ~ x1))))
        @test occursin("not implemented", msg(bf(@formula(yi ~ x1 + meta_V(vi) + (0 + x1 | g)), @formula(sigma ~ 1))))
    end
end
